import { input, select, Separator } from '@inquirer/prompts'
import { logger } from '../../logger'
import type { Arguments } from './index'
import {
    Connector,
    type LazyCredential,
    ProjectFactory,
    ProjectInitValidation,
    type TemplateInfo,
    type Templates,
} from '@servicenow/sdk-api'

const appNamePrompt = async (defaultAppName: string = 'Now SDK Example App') => {
    function normalize(value: string) {
        return value.trim()
    }

    const raw = await input({
        message: 'Name of ServiceNow Application: ',
        default: defaultAppName,
        validate: (value) => ProjectInitValidation.validateAppName(normalize(value)) ?? true,
    })

    return normalize(raw)
}

const templatePrompt = async (templates: (TemplateInfo & { id: keyof Templates })[]) => {
    type Choice = { value: keyof Templates; name?: string; description?: string }
    const choices: (Separator | Choice)[] = []
    let lastCategory: string | undefined
    for (const template of templates) {
        if (template.category && lastCategory !== template.category) {
            choices.push(new Separator(`-- ${template.category} --`))
            lastCategory = template.category
        }
        choices.push({
            name: template.name,
            value: template.id,
            description: template.description,
        })
    }
    const raw = await select({
        message: 'Select a template:',
        pageSize: choices.length,
        choices,
    })
    return raw
}

const globalPrompt = async () => {
    const raw = await select({
        message: 'Create a Global/Scoped App?',
        choices: [
            {
                name: 'Scoped',
                value: 'scoped',
                description:
                    'A scope protects application functionality by identifying and restricting access to application files and data. This ensures the application does not disrupt core business services and that other applications cannot interfere with its normal functioning.',
            },
            {
                name: 'Global',
                value: 'global',
                description:
                    'Global scope allows the application to be accessible to other globally scoped applications. They do not offer the same protections as scoped apps. Global applications are eligible for upload to the application repository, but not to the ServiceNow Store.',
            },
        ],
    })
    return raw
}

const scopeNamePrompt = async (defaultScopeName?: string | undefined) => {
    function normalize(value: string) {
        return value.trim()
    }

    const raw = await input({
        message: 'Scope name: ',
        default: defaultScopeName,
        transformer: normalize,
        // intentionally not validating the vendorPrefix here, so that users
        // can optionally override the whole scope (useful for internal/maint devs)
        validate: (value) => ProjectInitValidation.validateScopeName(normalize(value)) ?? true,
    })

    return normalize(raw)
}

const packageNamePrompt: (name: string) => Promise<string> = (generatedName: string) =>
    input({
        message: `NPM package name: `,
        default: generatedName,
        validate(pkgName: string) {
            const error = ProjectInitValidation.validateNpmPackageName(pkgName)
            if (error) {
                return error
            }
            return true
        },
    })

const needPrompt = (context: Arguments, requiredFields: string[]) => {
    return requiredFields.some((field) => !context[field as keyof Arguments])
}

function getVendorPrefix(connector: Connector): Promise<string> {
    try {
        return connector.appCreatorVendorPrefix()
    } catch {
        return Promise.resolve('x_')
    }
}

export async function getPromptAnswers(
    context: Arguments,
    credential: LazyCredential,
    templates: (TemplateInfo & { id: keyof Templates })[]
): Promise<{ appName: string; packageName: string; scopeName: string; templateId: keyof Templates }> {
    if (
        !needPrompt(context, ['appName', 'packageName', 'scopeName']) &&
        context.template &&
        context.template in templates
    ) {
        return { ...context, templateId: context.template } as {
            appName: string
            packageName: string
            scopeName: string
            templateId: keyof Templates
        }
    }

    const hasExistingTemplate = templates.some(({ id }) => id === context.template)
    const templateId = context.template && hasExistingTemplate ? context.template : await templatePrompt(templates)

    const appName = context.appName ?? (await appNamePrompt(context.appName))
    const packageName = context.packageName ?? (await packageNamePrompt(ProjectFactory.createNpmPackageName(appName)))

    const vendorPrefix = (await getVendorPrefix(new Connector(credential))) ?? 'x_'

    const defaultScopeName = `${vendorPrefix}${packageName.toLowerCase().replaceAll(/\W/g, '_')}`
        .slice(0, 18)
        .replace(/_$/, '')
    const scopeName =
        context.scopeName ?? ((await globalPrompt()) === 'global' ? 'global' : await scopeNamePrompt(defaultScopeName))
    return {
        appName,
        packageName,
        scopeName,
        templateId,
    }
}

export async function getPromptAnswersForInitConvert(context: Arguments) {
    if (!needPrompt(context, ['packageName'])) {
        return { ...context }
    }

    logger.info(`Please provide the missing required fields:`)
    const packageName = await packageNamePrompt('')
    return {
        packageName,
    }
}

export async function getPromptAnswersForInitApply(
    context: Arguments,
    templates: (TemplateInfo & { id: keyof Templates })[]
): Promise<{ templateId: keyof Templates; params: Record<string, string> }> {
    const hasExistingTemplate = templates.some(({ id }) => id === context.template)
    const templateId = context.template && hasExistingTemplate ? context.template : await templatePrompt(templates)
    const template = templates.find(({ id }) => id === templateId)
    const params: Record<string, string> = {}
    if (template?.params) {
        logger.info(`Template "${template.name}" requires additional parameters:`)
        for (const [paramName, param] of Object.entries(template.params)) {
            const answer = await input({
                message: `${param.label}: `,
                default: param.default,
                validate: (value) => (value.trim().length === 0 ? 'Value cannot be empty' : true),
            })
            params[paramName] = answer.trim()
        }
    }

    return { templateId, params }
}
